skin:
#s88 .stage{background:#fff;color:#1a1a1a}
#s88 .stage::before{content:'';position:absolute;inset:0;background:radial-gradient(50% 42% at 86% 6%,#ffd1001f,transparent 60%);pointer-events:none}
#s88 .d-nav{background:#fffbe6;border:1px solid #f0e39e;border-radius:14px}
#s88 .d-logo{font-weight:800;color:#1a1a1a}
#s88 .d-links span{opacity:.62}#s88 .d-links span:hover{opacity:1;background:#ffd10033;border-radius:8px}
#s88 .d-h{letter-spacing:-.02em;font-weight:800}
#s88 .d-p{color:#6b6b6b}
#s88 .d-btn{background:#ffd100;color:#1a1a1a;font-weight:800;border-radius:999px}
#s88 .d-btn:hover{background:#ffc400;transform:translateY(-1px)}
#s88 .d-btn.ghost{background:#fff;color:#1a1a1a;border:2px solid #ffd100}
#s88 .d-input{background:#fff;border:2px solid #ffd100;border-radius:999px;color:#1a1a1a}
#s88 .d-badge{background:#ffd100;color:#1a1a1a;border-radius:6px;font-weight:700}
#s88 .d-prog{height:5px;background:#f0ead0;border-radius:99px}#s88 .d-prog i{background:linear-gradient(90deg,#ffe45c,#ffd100)}
#s88 .d-card{background:#fff;border:1px solid #f2eecd;border-radius:14px;box-shadow:0 6px 18px #ffd10024}
